// The 25 passages closest in MEANING to the query — now let GPT judge which actually ANSWER it.
const query = $('When Executed by Another Workflow').first().json.query;
const passages = $input.all().map((it, i) => ({
  i,
  file_name: it.json.document?.metadata?.file_name,
  file_id: it.json.document?.metadata?.file_id,
  chunk_index: it.json.document?.metadata?.chunk_index,
  similarity: it.json.score,
  content: it.json.document?.pageContent ?? '',
}));

// Show GPT the first 3,000 characters of each passage (headings + opening are enough to judge relevance)
const listing = passages.map(p => `[${p.i}] (${p.file_name})\n${p.content.slice(0, 3000)}`).join('\n\n---\n\n');

const prompt = `You are ranking search results for a question.
Question: ${query}

Below are ${passages.length} passages, numbered [n]. Choose up to 4 that most DIRECTLY help answer the question, best first.
Prefer passages containing the actual answer (steps, values, definitions, requirements) over passages that are only on a similar topic.
Return ONLY json: {"best": [n, n, ...]}. If none of them helps answer the question, return {"best": []}.

${listing}`;

return [{ json: { prompt, passages } }];

// Turn GPT's choice into the tool's answer. If its reply is unusable, fall back to plain vector order —
// a search must never fail just because the reranker did.
const { passages } = $('Build rerank prompt').first().json;
const reply = $input.first().json;

let parsed = reply;                                         // n8n usually parses JSON replies already…
if (!Array.isArray(parsed.best)) {                          // …older versions give raw text
  try { parsed = JSON.parse(reply.text ?? reply.response ?? '{}'); } catch (e) { parsed = {}; }
}
let best = Array.isArray(parsed.best)
  ? parsed.best.map(Number).filter(n => Number.isInteger(n) && passages[n])
  : null;
const reranked = best !== null;
if (!reranked) best = [0, 1, 2, 3].filter(n => passages[n]);

const results = [...new Set(best)].slice(0, 4).map(n => ({
  file_name: passages[n].file_name,
  file_id: passages[n].file_id,
  chunk_index: passages[n].chunk_index,
  content: passages[n].content,                            // full text, image links included
}));
return [{ json: { reranked, candidates: passages.length, picked: [...new Set(best)].slice(0, 4), results } }];
